const { pathToFileURL } = await import('node:url');
const { join } = await import('node:path');
let mod;
try {
  mod = await import(pathToFileURL(join(process.cwd(), 'scripts/dev-helpers/automated-rebase-reverify.mjs')).href);
} catch (error) {
  console.error('MODULE_NOT_YET_PRESENT: ' + error.message);
  process.exit(1);
}

const enc = (obj) => Buffer.from(JSON.stringify(obj, null, 2) + '\n');
const original = { schema_version: 'dev-gov-v1-unit-definition', unit: 'X', base_sha: 'a'.repeat(40), required_red: [{ id: 'r1' }] };
// Adversarial fixture: base_sha already drifted BEFORE this automation touched anything -- the
// exact circularity scenario the design's second cold-review pass found (AUTOMATED-REBASE-REVERIFY
// -DESIGN-2026-09-30.md §2): a single post-merge 'byte-identical except base_sha' check cannot tell
// this apart from the automation's own legitimate edit.
const preAutomationDrifted = { ...original, base_sha: 'd'.repeat(40) };
const result = mod.phase1VerifyOriginalIdentity(enc(preAutomationDrifted), enc(original));
if (result.ok !== false || result.stop !== 'STOP_NEW_REVIEW_REQUIRED') {
  console.error('PHASE1_DID_NOT_REJECT_PRE_EXISTING_DRIFT: ' + JSON.stringify(result));
  process.exit(1);
}
console.log('phase1 correctly rejected pre-existing base_sha drift');

