const enc = (obj) => Buffer.from(JSON.stringify(obj, null, 2) + '\n');
const preEdit = { schema_version: 'dev-gov-v1-unit-definition', unit: 'X', base_sha: 'a'.repeat(40), required_red: [{ id: 'r1' }] };
// Adversarial fixture: an edit disguised as a base_sha-only change that ALSO tampers with another
// field -- the other half of the same circularity defect (§1.3): Phase 2 must diff against the
// Phase-1 snapshot and require the changed-key set to be exactly {"base_sha"}.
const sneakyEdit = { ...preEdit, base_sha: 'b'.repeat(40), unit: 'X-TAMPERED' };
const result = mod.phase2VerifyOwnEdit(enc(preEdit), enc(sneakyEdit), 'b'.repeat(40));
if (result.ok !== false || result.stop !== 'STOP_NEW_REVIEW_REQUIRED') {
  console.error('PHASE2_DID_NOT_REJECT_SNEAKY_EDIT: ' + JSON.stringify(result));
  process.exit(1);
}
console.log('phase2 correctly rejected an edit disguised as base_sha-only');

