// §1 scope gate: a PR that is BEHIND but CONFLICTING (not cleanly mergeable) must never be treated
// as in-scope for this automation -- that needs a real human rebase, not a mechanical one.
const result = mod.classifyStaleness({ mergeStateStatus: 'BEHIND', mergeable: 'CONFLICTING' });
if (result.inScope !== false || result.stop !== mod.STOP.NOT_MERGEABLE) {
  console.error('STALENESS_WRONGLY_IN_SCOPE_FOR_CONFLICTING_PR: ' + JSON.stringify(result));
  process.exit(1);
}
console.log('staleness gate correctly excluded a CONFLICTING PR');

